const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let selectedDays=30,pollTimer,currentDashboard,currentReport,currentWorkouts=[],currentWorkoutIndex=-1,assistantHistory=[],assistantPendingImage=null;
const fmt=(n,d=0)=>n==null?'—':Number(n).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const present=a=>a.filter(v=>v!=null&&!Number.isNaN(Number(v)));
const avg=a=>{const x=present(a);return x.length?x.reduce((s,v)=>s+Number(v),0)/x.length:null};
const esc=value=>String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}
async function jsonFetch(url,opts){const r=await fetch(url,opts),j=await r.json();if(!r.ok)throw new Error(j.message||j.error||'请求失败');return j}
function setVisible(id){['setup','connect','dashboard'].forEach(x=>$('#'+x).classList.toggle('hidden',x!==id))}
function timeLabel(value){if(!value)return'';const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}
function todayIso(){const now=new Date(),pad=n=>String(n).padStart(2,'0');return`${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`}
function dayLabel(day){if(!day)return'最近记录';if(day===todayIso())return'今天';const date=new Date(day+'T00:00:00');return Number.isNaN(date.getTime())?day:date.toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})+' 数据'}
function syncIndicator(status){const running=status?.running;$('#syncDot').className='dot '+(running?'working':'ready');$('#syncLabel').textContent=running?'正在同步…':status?.last_sync?`更新于 ${timeLabel(status.last_sync)}`:'准备就绪';$('#syncBtn').disabled=!!running}
