async function boot(){try{const s=await jsonFetch('/api/status');syncIndicator({...s.sync_status,last_sync:s.last_sync});if(!s.configured){setVisible('setup')}else if(!s.connected){setVisible('connect')}else{setVisible('dashboard');permissionState(s.needs_extended_consent);await loadDashboard();loadDailyBrief();if(s.sync_status?.running)startPolling()}}catch(e){toast(e.message)}}
