$('#copyRedirect').addEventListener('click',async()=>{await navigator.clipboard.writeText($('#redirectUri').value);toast('回调地址已复制')});
$('#syncBtn').addEventListener('click',async()=>{try{await jsonFetch('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({days:2})});toast('正在获取今天的最新数据');startPolling()}catch(e){toast(e.message)}});
$$('.range-switch button').forEach(b=>b.addEventListener('click',()=>{$$('.range-switch button').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectedDays=Number(b.dataset.days);loadDashboard()}));
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{try{const s=await jsonFetch('/api/status');syncIndicator({...s.sync_status,last_sync:s.last_sync});permissionState(s.needs_extended_consent);if(!s.sync_status?.running){clearInterval(pollTimer);await loadDashboard();toast(s.sync_status?.errors?.length?'同步完成，少数指标暂无数据或不可用':'数据已更新')}}catch(e){clearInterval(pollTimer);toast(e.message)}},3000)}
function lastValue(series,key){for(let i=series.length-1;i>=0;i--)if(series[i][key]!=null)return{value:series[i][key],day:series[i].day,row:series[i]};return null}
