function spark(el,series,key,color){const vals=series.slice(-14).map(x=>x[key]),clean=present(vals);if(clean.length<2){$(el).innerHTML='';return}const min=Math.min(...clean),max=Math.max(...clean),range=max-min||1,w=220,h=38,points=vals.map((v,i)=>v==null?null:[i/(vals.length-1)*w,h-(v-min)/range*(h-7)-3]);let d='',pen=false;points.forEach(p=>{if(!p){pen=false;return}d+=(pen?'L':'M')+p[0].toFixed(1)+','+p[1].toFixed(1)+' ';pen=true});$(el).innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path d="${d}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M0 ${h-1}H${w}" stroke="#edf0ee"/></svg>`}
function lineChart(el,series){const rows=series.filter(x=>x.steps!=null||x.active_zone_minutes!=null),w=750,h=220,p=24;if(!rows.length){$(el).innerHTML='<div class="empty">同步后显示活动趋势</div>';return}const max=Math.max(...rows.map(x=>Number(x.steps||0)),1),map=(v,i)=>[p+i/Math.max(rows.length-1,1)*(w-p*2),h-p-Number(v||0)/max*(h-p*2)],path=key=>rows.map((r,i)=>map(key==='active_zone_minutes'?Number(r[key]||0)*120:r[key],i)).map((point,i)=>(i?'L':'M')+point[0].toFixed(1)+','+point[1].toFixed(1)).join(' ');let grid='';for(let i=0;i<5;i++){const y=p+i*(h-p*2)/4;grid+=`<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}" stroke="#e9eeeb"/><text x="0" y="${y+3}" fill="#9aa59f" font-size="9">${fmt(max*(1-i/4))}</text>`}$(el).innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}<defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#62bf8f" stop-opacity=".25"/><stop offset="1" stop-color="#62bf8f" stop-opacity="0"/></linearGradient></defs><path d="${path('steps')} L${w-p},${h-p} L${p},${h-p}Z" fill="url(#area)"/><path d="${path('steps')}" fill="none" stroke="#62bf8f" stroke-width="3" vector-effect="non-scaling-stroke"/><path d="${path('active_zone_minutes')}" fill="none" stroke="#8f84e8" stroke-width="2" stroke-dasharray="5 5" vector-effect="non-scaling-stroke"/></svg>`}
function sleepDonut(series){const row=lastValue(series,'sleep_minutes')?.row;if(!row){$('#sleepTotal').textContent='—';$('#sleepLegend').innerHTML='<span><small>暂无睡眠结构数据</small></span>';return}const stages=[['深睡','sleep_deep','#766bd7'],['REM','sleep_rem','#9d93e9'],['浅睡','sleep_light','#c3bcf2'],['清醒','sleep_awake','#e6e2fa']],vals=stages.map(x=>Number(row[x[1]]||0)),total=vals.reduce((a,b)=>a+b,0)||1;let at=0,parts=[];vals.forEach((v,i)=>{const next=at+v/total*100;parts.push(`${stages[i][2]} ${at}% ${next}%`);at=next});$('#sleepDonut').style.background=`conic-gradient(${parts.join(',')})`;$('#sleepTotal').textContent=duration(row.sleep_minutes);$('#sleepRangeLabel').textContent=row.day;$('#sleepLegend').innerHTML=stages.map((s,i)=>`<span style="--stage:${s[2]}"><b>${fmt(vals[i])} 分钟</b><small>${s[0]} · ${fmt(vals[i]/total*100)}%</small></span>`).join('')}
function renderSleepHistory(items){const rows=(items||[]).filter(x=>x.minutes_asleep!=null).slice(0,14).reverse();if(!rows.length){$('#sleepHistorySummary').textContent='暂无记录';$('#sleepHistoryGrid').innerHTML='<div class="empty small">继续同步后显示逐夜睡眠。</div>';return}const mean=avg(rows.map(x=>x.minutes_asleep)),eff=avg(rows.map(x=>x.efficiency));$('#sleepHistorySummary').textContent=`${rows.length} 晚 · 平均 ${duration(mean)}${eff==null?'':` · 效率 ${fmt(eff)}%`}`;$('#sleepHistoryGrid').innerHTML=rows.map(x=>{const fill=Math.max(12,Math.min(100,Number(x.minutes_asleep)/540*100)),label=x.day?.slice(5)||'—',detail=x.efficiency==null?'睡眠记录':`效率 ${fmt(x.efficiency)}%`;return`<div class="sleep-night" title="${esc(x.day)} ${esc(detail)}"><b>${esc(label)}</b><small>${esc(duration(x.minutes_asleep))}</small><span style="--sleep-fill:${fill}%"></span><em>${esc(detail)}</em></div>`}).join('')}
