function workoutsInRange(items,days=selectedDays){const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-Math.max(6,Number(days)-1));return(items||[]).filter(x=>{const day=new Date((x.day||'')+'T00:00:00');return!Number.isNaN(day.getTime())&&day>=cutoff})}
