function renderTrainingHeartRanges(items){const rows=items.map(item=>({item,index:currentWorkouts.indexOf(item),heart:trainingHeart(item)})).filter(x=>x.index>=0&&x.heart.min!=null&&x.heart.max!=null&&x.heart.avg!=null).slice(0,12);if(!rows.length){$('#trainingHeartChart').innerHTML='<div class="empty small">暂无逐次运动心率范围</div>';return}const low=Math.floor((Math.min(...rows.map(x=>x.heart.min))-5)/10)*10,high=Math.ceil((Math.max(...rows.map(x=>x.heart.max))+5)/10)*10,position=value=>Math.max(0,Math.min(100,(value-low)/(high-low||1)*100));$('#trainingHeartChart').innerHTML=rows.map(row=>`<button class="heart-range-row" type="button" data-training-workout="${row.index}"><span><b>${esc(exerciseLabel(row.item.type))}</b><small>${esc(row.item.day||'')}</small></span><div class="heart-range-track" style="--low:${position(row.heart.min)}%;--high:${position(row.heart.max)}%;--avg:${position(row.heart.avg)}%"><i></i><em></em><title>${fmt(row.heart.min)}–${fmt(row.heart.max)} bpm · 平均 ${fmt(row.heart.avg)} bpm</title></div><em>${fmt(row.heart.avg)}</em></button>`).join('')}
function renderTrainingCalendar(items){const today=new Date();today.setHours(0,0,0,0);const start=new Date(today);start.setDate(today.getDate()-41);const monday=(start.getDay()+6)%7,startAligned=new Date(start);startAligned.setDate(start.getDate()-monday);const byDay=new Map();items.forEach((item,index)=>{const row=byDay.get(item.day)||{minutes:0,count:0,calories:0,index};row.minutes+=Number(item.active_seconds||0)/60;row.count+=1;row.calories+=Number(item.summary?.caloriesKcal||0);byDay.set(item.day,row)});const cells=[],loads=[];for(let i=0;i<49;i++){const day=new Date(startAligned);day.setDate(startAligned.getDate()+i);if(day>today)break;const iso=day.toISOString().slice(0,10),row=byDay.get(iso);if(row)loads.push(row.minutes);cells.push({day,iso,row})}const maxLoad=Math.max(...loads,1);$('#trainingCalendar').innerHTML=cells.map(cell=>{const row=cell.row,level=row?Math.max(18,Math.round(row.minutes/maxLoad*85)):0;return`<button class="training-calendar-day ${row?'has-workout':''} ${cell.iso===todayIso()?'today':''}" type="button" ${row?`data-training-workout="${row.index}" style="--level:${level}"`: 'disabled'} title="${row?`${cell.iso} · ${row.count} 次 · ${fmt(row.minutes)} 分钟 · ${fmt(row.calories)} kcal`:cell.iso}"><b>${cell.day.getDate()}</b>${row?`<small>${row.count} 次</small><em>${fmt(row.minutes)} 分钟</em>`:'<small>—</small>'}</button>`}).join('');const activeDays=byDay.size,longest=(()=>{const active=new Set(byDay.keys()),cursor=new Date(today);let best=0,current=0;for(let i=0;i<90;i++){const iso=cursor.toISOString().slice(0,10);if(active.has(iso)){current++;best=Math.max(best,current)}else current=0;cursor.setDate(cursor.getDate()-1)}return best})(),restDays=Math.max(0,Math.min(42,Math.floor((today-start)/86400000)+1)-[...byDay.keys()].filter(day=>day>=start.toISOString().slice(0,10)).length);$('#trainingCalendarMeta').textContent=`${activeDays} 个训练日 · 最长连续 ${longest} 天`;return{activeDays,longest,restDays}}
