function renderDailyBrief(brief){const score=brief.score;$('#dailyBriefScore b').textContent=score==null?'—':fmt(score);$('#dailyBriefScore').style.setProperty('--score',score||0);$('#dailyBriefLabel').textContent=brief.score_label||'建立基线中';$('#dailyBriefHeadline').textContent=brief.headline||'今日简报';$('#dailyBriefSummary').textContent=brief.summary||'';$('#dailyBriefMeta').textContent=`数据截至 ${brief.latest_data_day||'—'} · 每天 08:20 自动归档`;$('#dailyBriefMetrics').innerHTML=(brief.metrics||[]).map(item=>{const change=item.change_percent,trend=change==null?'基线积累中':`${change>=0?'↑':'↓'} ${fmt(Math.abs(change),1)}%`;return`<div><span>${esc(item.label)}</span><b>${esc(dailyMetricValue(item))}</b><small>${esc(item.day?dayLabel(item.day):'暂无数据')} · ${esc(trend)}</small></div>`}).join('');const alerts=brief.alerts||[];$('#dailyAlertCount').textContent=alerts.length?`${alerts.length} 项`:'状态稳定';$('#dailyAlerts').innerHTML=alerts.length?alerts.map(item=>`<div class="daily-alert severity-${esc(item.severity)}"><i></i><div><b>${esc(item.title)}</b><p>${esc(item.message)}</p><small>${esc(item.evidence)}</small></div></div>`).join(''):'<div class="daily-empty">没有达到个人趋势提醒条件的项目。</div>';$('#dailyActions').innerHTML=(brief.recommendations||[]).map((item,index)=>`<div><b>${index+1}</b><p>${esc(item)}</p></div>`).join('');const ai=$('#dailyBriefAi'),answer=brief.ai?.answer;if(answer){ai.classList.remove('hidden');ai.innerHTML=`<p class="eyebrow">CODEX DAILY ANALYSIS</p><h3>AI 今日解读</h3><div class="ai-rich">${aiMarkup(answer)}</div><small>${brief.ai.generated_at?`生成于 ${esc(timeLabel(brief.ai.generated_at))}`:'自动生成'} · 仅发送聚合指标</small>`}else{ai.classList.add('hidden');ai.innerHTML=''};$('#dailyBriefGenerate').textContent=answer?'重新生成 AI 今日解读':'✦ 生成 AI 今日解读'}
