function renderLongTerm(value){const trends=value.trends||[];$('#longTermMeta').textContent=`${value.attention_count||0} 项需留意 · ${value.positive_count||0} 项积极变化`;$('#longTermSummary').innerHTML=`<div class="${value.attention_count?'attention':'stable'}"><b>${value.attention_count?'存在持续偏离个人基线的指标':'近期整体接近个人基线'}</b><p>${esc(value.method||'')}</p></div>`;$('#longTermTrends').innerHTML=trends.map(item=>{const change=item.change_percent,amount=Math.min(50,Math.abs(change||0)),left=change>=0?50:50-amount,changeText=item.available?`${change>=0?'+':''}${fmt(change,1)}%`:'样本积累中';return`<div class="long-term-row ${esc(item.tone)}"><div><b>${esc(item.label)}</b><small>近 7 天 ${esc(longTermValue(item,item.recent))} · 基线 ${esc(longTermValue(item,item.baseline))}</small></div><div class="long-term-track"><i style="left:${left}%;width:${amount}%"></i><em></em></div><strong>${esc(changeText)}</strong></div>`}).join('');const history=(value.daily_history||[]).slice().reverse(),scores=history.map(x=>Number(x.score)).filter(Number.isFinite);$('#longTermHistoryMeta').textContent=history.length?`${history.length} 天归档 · 平均 ${fmt(avg(scores),1)}`:'从今天开始积累';if(!scores.length){$('#longTermHistory').innerHTML='<div class="daily-empty">每日自动简报归档后会形成恢复历史。</div>';return}const w=700,h=120,p=14,points=history.map((row,i)=>({x:p+i/Math.max(history.length-1,1)*(w-p*2),y:h-p-(Number(row.score||0)/100)*(h-p*2),score:row.score,day:row.day})),line=points.map((point,i)=>(i?'L':'M')+point.x.toFixed(1)+','+point.y.toFixed(1)).join(' ');$('#longTermHistory').innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${p}" y1="${h-p-60/100*(h-p*2)}" x2="${w-p}" y2="${h-p-60/100*(h-p*2)}" stroke="#dfe6e2" stroke-dasharray="5 5"/><path d="${line}" fill="none" stroke="#55b883" stroke-width="3" vector-effect="non-scaling-stroke"/>${points.map(point=>`<circle cx="${point.x}" cy="${point.y}" r="4" fill="#2f8b63"><title>${esc(point.day)} · ${fmt(point.score)}</title></circle>`).join('')}</svg>`}
