function byteSize(value){const bytes=Number(value||0);if(bytes<1024)return fmt(bytes)+' B';if(bytes<1024*1024)return fmt(bytes/1024,1)+' KB';return fmt(bytes/1024/1024,1)+' MB'}
function renderBackupStatus(value){const latest=value.latest||{},rows=value.backups||[];$('#backupLatest').textContent=latest.created_at?new Date(latest.created_at).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'}):'尚未备份';$('#backupIntegrity').textContent=latest.ok?`完整性 ${latest.integrity||'ok'} · SHA-256 已校验`:'等待首次自动备份';$('#backupCount').textContent=fmt(value.count||0)+' 份';$('#backupSize').textContent=byteSize(value.total_size_bytes);$('#backupScope').textContent=value.scope||'';$('#backupExcluded').textContent=value.excluded||'';$('#backupRestore').textContent=value.restore||'';$('#backupList').innerHTML=rows.length?rows.slice(0,8).map((row,index)=>`<div><span>${index===0?'最新':'历史'}</span><b>${esc(row.file.replace('air-health-','').replace('.tar.gz',''))}</b><small>${byteSize(row.size_bytes)}</small></div>`).join(''):'<div class="daily-empty">今晚 03:40 将自动创建第一份备份，也可以现在手动创建。</div>'}
async function loadBackupStatus(){try{renderBackupStatus(await jsonFetch('/api/backup-status'))}catch(e){toast('备份状态加载失败：'+e.message)}}
$('#createBackup').addEventListener('click',async()=>{const button=$('#createBackup');button.disabled=true;button.textContent='正在备份并校验…';try{const value=await jsonFetch('/api/backup/create',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!value.ok)throw new Error(value.message||'备份失败');await loadBackupStatus();toast('备份已创建并通过完整性检查')}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='立即创建备份'}});
const viewCopy={overview:['CONTROL CENTER','今日健康总览','从恢复、活动、睡眠与生命体征快速判断今天的状态。'],activity:['ACTIVITY & TRAINING','活动与训练','查看日常活动、训练负荷、心率区间与每次健身运动。'],sleep:['SLEEP & RECOVERY','睡眠与恢复','回顾睡眠结构、恢复驱动因素与近期睡眠趋势。'],health:['HEART & HEALTH','心脏与健康','集中查看心率、HRV、血氧、呼吸率、皮温与身体指标。'],explore:['METRIC EXPLORER','趋势探索','自由选择两个指标，观察它们在同一时间轴上的变化。'],report:['WEEKLY RECAP','健康数据周报','汇总这一周的活动、睡眠、恢复和生命体征，并与前一周比较。'],coach:['PRIVATE AI COACH','AI 健康分析','让 Codex 根据聚合数据回答你的个性化健康趋势问题。'],assistant:['GENERAL AI ASSISTANT','随身 AI 助手','在当前网页中完成通用问答、总结、翻译、写作、代码和计划拆解。']};
function switchView(view){if(!viewCopy[view])view='overview';document.body.dataset.view=view;$$('.section-nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const copy=viewCopy[view];$('#viewEyebrow').textContent=copy[0];$('#viewTitle').textContent=copy[1];$('#viewDescription').textContent=copy[2];if(view==='activity')loadTrainingPlan();if(view==='report'){loadWeeklyReport();loadBackupStatus()}if(view==='explore'){loadLongTerm();if(currentDashboard)renderExplorer()}history.replaceState(null,'',view==='overview'?'#overview':'#'+view);window.scrollTo({top:window.innerWidth<=580?0:70,behavior:'smooth'})}
$$('.section-nav button').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view)));
function metricOption(item){return`<option value="${esc(item.key)}">${esc(item.label)} · ${esc(item.unit)}</option>`}
function renderExplorerOptions(items){const selectA=$('#primaryMetric'),selectB=$('#compareMetric'),oldA=selectA.value||'sleep_minutes',oldB=selectB.value||'hrv';selectA.innerHTML=items.map(metricOption).join('');selectB.innerHTML=items.map(metricOption).join('');selectA.value=items.some(x=>x.key===oldA)?oldA:items[0]?.key||'';selectB.value=items.some(x=>x.key===oldB)?oldB:items[1]?.key||selectA.value;renderExplorer()}
function renderExplorer(){const metrics=currentDashboard?.metric_explorer||[],a=metrics.find(x=>x.key===$('#primaryMetric').value),b=metrics.find(x=>x.key===$('#compareMetric').value);if(!a||!b){$('#comparisonChart').innerHTML='<div class="empty">当前范围没有可探索的指标</div>';return}const days=[...new Set([...a.series.map(x=>x.day),...b.series.map(x=>x.day)])].sort(),mapA=new Map(a.series.map(x=>[x.day,Number(x.value)])),mapB=new Map(b.series.map(x=>[x.day,Number(x.value)])),normalize=(map,min,max,day)=>map.has(day)?(map.get(day)-min)/(max-min||1):null,w=900,h=235,p=28,path=(map,min,max)=>{let d='',pen=false;days.forEach((day,i)=>{const v=normalize(map,min,max,day);if(v==null){pen=false;return}const x=p+i/Math.max(days.length-1,1)*(w-p*2),y=h-p-v*(h-p*2);d+=(pen?'L':'M')+x.toFixed(1)+','+y.toFixed(1)+' ';pen=true});return d};let grid='';for(let i=0;i<5;i++){const y=p+i*(h-p*2)/4;grid+=`<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}" stroke="#e7ece9"/>`}const labels=days.filter((_,i)=>i===0||i===days.length-1||i===Math.floor(days.length/2)).map(day=>{const i=days.indexOf(day),x=p+i/Math.max(days.length-1,1)*(w-p*2);return`<text x="${x}" y="${h-3}" text-anchor="middle" fill="#89968f" font-size="10">${esc(day.slice(5))}</text>`}).join('');$('#comparisonChart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${grid}<path d="${path(mapA,a.minimum,a.maximum)}" fill="none" stroke="#2e9368" stroke-width="3" vector-effect="non-scaling-stroke"/><path d="${path(mapB,b.minimum,b.maximum)}" fill="none" stroke="#8f84e8" stroke-width="3" vector-effect="non-scaling-stroke"/>${labels}</svg>`;$('#explorerCoverage').innerHTML=`<span class="line-key" style="--line-color:#2e9368">${esc(a.label)}</span>　<span class="line-key" style="--line-color:#8f84e8">${esc(b.label)}</span>`;const stat=(title,value)=>`<div class="explorer-stat"><small>${esc(title)}</small><b>${esc(value)}</b></div>`;$('#explorerStats').innerHTML=stat(a.label+' 最新',fmt(a.latest.value,1)+' '+a.unit)+stat(a.label+' 平均',fmt(a.average,1))+stat(a.label+' 范围',fmt(a.minimum,1)+'–'+fmt(a.maximum,1))+stat(b.label+' 最新',fmt(b.latest.value,1)+' '+b.unit)+stat(b.label+' 平均',fmt(b.average,1))+stat(b.label+' 范围',fmt(b.minimum,1)+'–'+fmt(b.maximum,1))}
$('#primaryMetric').addEventListener('change',renderExplorer);$('#compareMetric').addEventListener('change',renderExplorer);$('#swapMetrics').addEventListener('click',()=>{const a=$('#primaryMetric').value;$('#primaryMetric').value=$('#compareMetric').value;$('#compareMetric').value=a;renderExplorer()});
function reportValue(item){if(item.value==null)return'—';const d=['distance_km','hrv','resting_heart_rate','spo2_avg','respiratory_rate'].includes(item.key)?1:0;return fmt(item.value,d)}
function reportList(el,items,empty){$(el).innerHTML=(items?.length?items:[empty]).map(x=>`<p>${esc(x)}</p>`).join('')}
function aiMarkup(value){const lines=esc(value).split(/\r?\n/),out=[];let list='',inCode=false,code=[];const inline=line=>line.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');const close=()=>{if(list){out.push(`</${list}>`);list=''}};for(const raw of lines){const line=raw.trim();if(line.startsWith('```')){close();if(inCode){out.push(`<pre><code>${code.join('\n')}</code></pre>`);code=[];inCode=false}else inCode=true;continue}if(inCode){code.push(raw);continue}if(!line){close();continue}let match;if((match=line.match(/^###\s+(.+)/))){close();out.push(`<h4>${inline(match[1])}</h4>`)}else if((match=line.match(/^##\s+(.+)/))){close();out.push(`<h3>${inline(match[1])}</h3>`)}else if((match=line.match(/^[-*]\s+(.+)/))){if(list!=='ul'){close();list='ul';out.push('<ul>')}out.push(`<li>${inline(match[1])}</li>`)}else if((match=line.match(/^\d+[.、]\s*(.+)/))){if(list!=='ol'){close();list='ol';out.push('<ol>')}out.push(`<li>${inline(match[1])}</li>`)}else{close();out.push(`<p>${inline(line)}</p>`)}}close();if(inCode&&code.length)out.push(`<pre><code>${code.join('\n')}</code></pre>`);return out.join('')}
function renderWeeklyReport(report){currentReport=report;const period=report.period||{};$('#reportPeriod').textContent=`${period.start||'—'} 至 ${period.end||'—'} · ${report.coverage_days||0} 天有数据 · ${report.workout_count||0} 次运动`;$('#reportRecovery').textContent=report.analytics?.recovery?.available?fmt(report.analytics.recovery.score):'—';const keys=['steps','exercise_minutes','sleep_minutes','hrv','resting_heart_rate'],metrics=(report.metrics||[]).filter(x=>keys.includes(x.key));$('#reportMetrics').innerHTML=metrics.map(x=>{const change=x.change_percent,trend=change==null?'暂无上周基线':`${change>=0?'↑':'↓'} ${fmt(Math.abs(change),1)}% 较上周`;return`<div class="report-metric"><span>${esc(x.label)}</span><b>${esc(reportValue(x))}</b><small>${esc(x.unit)} · ${esc(trend)}</small></div>`}).join('');reportList('#reportHighlights',report.highlights,'本周指标整体稳定，继续积累个人基线。');reportList('#reportConcerns',report.concerns,'当前没有达到规则阈值的异常趋势。');reportList('#reportRecommendations',report.recommendations,'保持规律作息与适量活动，并结合主观感受调整。');let ai=$('#reportAiNarrative');if(!ai){ai=document.createElement('article');ai.id='reportAiNarrative';ai.className='report-ai-narrative';$('#weeklyModule').insertBefore(ai,$('.report-foot'))}ai.classList.remove('expanded');ai.innerHTML=report.ai?.answer?`<p class="eyebrow">CODEX WEEKLY ANALYSIS</p><h3>AI 周度解读</h3><div class="ai-rich">${aiMarkup(report.ai.answer)}</div><button class="ai-expand" type="button" aria-expanded="false">展开完整解读</button>`:'';const expand=ai.querySelector('.ai-expand');if(expand)expand.addEventListener('click',()=>{const open=ai.classList.toggle('expanded');expand.textContent=open?'收起解读':'展开完整解读';expand.setAttribute('aria-expanded',String(open))})}
function renderReportArchive(value){$('#reportSchedule').textContent=value.weekly_schedule||'每周一自动生成';const rows=value.weekly||[];$('#reportArchiveList').innerHTML=rows.length?rows.slice(0,6).map(item=>`<span><b>${esc(item.end||'')}</b><small>${fmt(item.coverage_days||0)} 天数据 · ${fmt(item.workout_count||0)} 次运动${item.has_ai?' · AI':''}</small></span>`).join(''):'<span><b>等待首次自动归档</b><small>下周一生成上一完整周</small></span>'}
async function loadWeeklyReport(){try{const [report,archive]=await Promise.all([jsonFetch('/api/weekly-report'),jsonFetch('/api/report-archive')]);renderWeeklyReport(report);renderReportArchive(archive)}catch(e){toast(e.message)}}
$('#refreshReport').addEventListener('click',async()=>{try{$('#refreshReport').disabled=true;const value=await jsonFetch('/api/weekly-report/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});renderWeeklyReport(value.report);renderReportArchive(await jsonFetch('/api/report-archive'));toast('本周周报已重新生成并归档')}catch(e){toast(e.message)}finally{$('#refreshReport').disabled=false}});
const coachGuidance={
  general:{label:'综合健康',tips:[['先看趋势，不追单点','把睡眠、静息心率、HRV 与训练负荷放在 7–30 天趋势中观察，比单日高低更有意义。','结合最近 30 天睡眠、HRV、静息心率和训练负荷，找出最值得关注的趋势。'],['恢复也需要计划','连续高强度训练、睡眠缩短或静息心率抬升时，安排轻活动或恢复日。','我的近期训练与恢复是否匹配？请指出证据并给出下一周安排。'],['让目标具体可执行','把“多运动”改成时间、频率和场景明确的小目标，更容易长期坚持。','基于我的活动水平，设计三个本周能执行并能衡量的小目标。'],['睡眠是基础变量','固定入睡起床时间，并观察睡眠时长变化是否伴随 HRV、静息心率和主观状态变化。','分析睡眠与 HRV、静息心率和训练表现的关系，说明相关性与数据限制。']],questions:['我最近 30 天最明显的健康趋势是什么？请按重要性排序。','睡眠、HRV、静息心率和训练负荷之间可能有什么关系？','哪些指标出现什么变化时值得连续观察，而不是只看单日？','结合最近运动和恢复，未来 7 天应该如何安排？','我的数据覆盖有哪些缺口，会影响哪些判断？','给我制定三个本周可执行、可量化的健康目标。']},
  uric:{label:'尿酸管理',tips:[['化验值不能由手环推断','步数、心率或体重趋势不能代替血尿酸和肾功能检查；解读时应补充化验日期、症状和用药。','我的手环数据能为尿酸管理提供哪些参考，哪些结论必须依赖化验？'],['优先减少含糖饮料与酒精','少喝含糖饮料和酒精，并以水作为主要饮品，是更容易执行的生活方式起点。','请给我一个减少含糖饮料与酒精、支持尿酸管理的 4 周行动方案。'],['避免激进减重与脱水','可持续减重可能有帮助，但极端节食、剧烈运动后脱水不适合作为长期策略。','结合我的体重和活动趋势，设计兼顾尿酸管理的稳妥减重与运动方案。'],['饮食看整体结构','减少内脏、过量红肉及部分高嘌呤海鲜，同时增加蔬果、全谷物和适合个人情况的低脂乳制品。','如何把尿酸友好的饮食原则转成一周可执行的餐食选择？'],['生活方式不能替代处方','反复痛风发作或已有痛风石时，生活方式通常不能代替医生制定的降尿酸治疗。','痛风长期管理中，生活方式、化验复查与处方治疗分别承担什么作用？']],questions:['结合我的体重、运动和恢复趋势，哪些因素可能不利于尿酸管理？','血尿酸偏高时，饮水、酒精、含糖饮料、红肉和海鲜应该怎样调整？','如何减脂和运动，避免快速减重、过度训练或脱水带来的风险？','痛风急性发作与长期尿酸管理有什么区别？哪些情况应尽快就医？','如果正在服用降尿酸药，日常观察和复查应关注什么？不要建议调整药量。','请根据我补充的血尿酸、肾功能、发作史和用药信息，整理一份就诊沟通清单。']},
  glucose:{label:'血糖与控糖',tips:[['记录餐前后差异','如有血糖仪或 CGM，可按医疗团队建议记录餐前、餐后、活动和饮食，寻找个人反应模式。','如何把餐食、餐前后血糖和活动记录整理成可分析的日志？'],['餐后从短时活动开始','身体状况允许时，可从餐后短时间步行开始，逐步建立规律活动习惯。','结合我的活动水平，制定循序渐进的餐后活动计划，并说明低血糖注意事项。'],['用餐盘法降低决策负担','增加非淀粉蔬菜，搭配适量蛋白质与主食，比只盯着“不能吃什么”更可持续。','请用餐盘法给出适合控糖的一日饮食组织示例，不替代营养师处方。'],['不跳餐，留意低血糖','使用胰岛素或某些降糖药时，跳餐、饮酒或突然增加运动可能提高低血糖风险。','如果正在使用降糖药，开始运动前需要向医生确认哪些低血糖安全问题？'],['睡眠和压力也要记录','睡眠不足、压力和生病都可能影响血糖；与饮食、活动一起记录更有解释力。','分析我的睡眠、压力替代指标和活动趋势可能如何影响控糖行为。']],questions:['结合睡眠、运动和体重趋势，给出有利于血糖管理的可执行建议，并说明缺少哪些化验数据。','空腹血糖、餐后血糖、糖化血红蛋白分别反映什么？我该如何准备记录？','如何安排餐后步行和每周运动，同时防范低血糖风险？','怎样用餐盘法、碳水分量和进餐规律改善饮食结构？','睡眠不足、压力和高强度训练可能怎样影响血糖波动？','如果我补充血糖、HbA1c、用药和症状，请帮我整理趋势与就医提问，不诊断或调药。']},
  body:{label:'减脂增肌',tips:[['减脂也要保护恢复','饮食调整、力量训练和睡眠要同时考虑；长期疲劳与表现下降可能提示恢复不足。','结合我的睡眠、HRV 和训练量，判断当前减脂计划是否可能影响恢复。'],['每周保留力量训练','成年人可把大肌群力量训练安排在每周至少两天，并根据恢复逐步增加。','依据我的训练记录设计每周力量训练框架，覆盖大肌群并安排恢复日。'],['有氧与力量不必二选一','有氧支持心肺与能量消耗，力量训练支持肌力与瘦体重，关键是总量和恢复匹配。','分析我目前有氧与力量训练比例，并给出减脂增肌兼顾的调整建议。'],['看体围、表现和趋势','体重短期受水分影响；腰围、力量表现、训练完成度和数周趋势能提供更多信息。','除了体重，我应该怎样组合腰围、训练表现和手环指标评估进展？'],['选择可长期执行的饮食','温和、稳定且能保持的饮食结构，通常比短期极端限制更有利于维持结果。','帮我把减脂饮食目标改写成一组无需精确计算热量的日常规则。']],questions:['结合我的运动、睡眠和恢复，设计一个减脂同时尽量保肌的 4 周框架。','我目前有氧、力量、活动量和恢复日的结构是否均衡？','如何设置可持续的饮食与活动目标，避免过度节食和快速减重？','增肌期间如何安排渐进负荷、训练频率与恢复观察指标？','体重没有明显变化时，如何用腰围、力量表现和趋势判断身体重组？','如果有高尿酸或血糖问题，减脂增肌计划需要额外注意什么？']}
};
let coachTopic='general',coachTipOffset=0;
const coachTopicKeys=Object.keys(coachGuidance);
function coachSelectQuestion(question){$('#coachQuestion').value=question;$('#coachQuestion').focus();$('#coachQuestion').scrollIntoView({behavior:'smooth',block:'center'})}
function renderCoachTips(){const now=new Date(),seed=Math.floor(Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())/86400000),cards=coachTopicKeys.map((key,index)=>{const topic=coachGuidance[key],tip=topic.tips[(seed+coachTipOffset+index*2)%topic.tips.length];return`<button class="coach-tip" type="button" data-topic="${key}" data-coach-question="${esc(tip[2])}"><small>${esc(topic.label.toUpperCase())}</small><b>${esc(tip[0])}</b><p>${esc(tip[1])}</p><span>结合我的数据分析 →</span></button>`});$('#coachTips').innerHTML=cards.join('');$('#coachTipsDate').textContent=`${now.toLocaleDateString('zh-CN',{month:'long',day:'numeric'})} · 每天自动轮换`}
function renderCoachQuestions(){$$('#coachFocusGrid [data-coach-topic]').forEach(button=>button.classList.toggle('active',button.dataset.coachTopic===coachTopic));const topic=coachGuidance[coachTopic];$('#coachTopicTitle').textContent=topic.label+'常见问题';$('#coachQuestions').innerHTML=topic.questions.map(question=>`<button type="button" data-coach-question="${esc(question)}">${esc(question)}</button>`).join('')}
function renderCoachGuidance(){renderCoachTips();renderCoachQuestions()}
$('#coachFocusGrid').addEventListener('click',event=>{const button=event.target.closest('[data-coach-topic]');if(!button||!coachGuidance[button.dataset.coachTopic])return;coachTopic=button.dataset.coachTopic;renderCoachQuestions()});
$('#coachTipsRefresh').addEventListener('click',()=>{coachTipOffset++;renderCoachTips()});
$('#coachTips').addEventListener('click',event=>{const button=event.target.closest('[data-coach-question]');if(button)coachSelectQuestion(button.dataset.coachQuestion)});
$('#coachQuestions').addEventListener('click',event=>{const button=event.target.closest('[data-coach-question]');if(button)coachSelectQuestion(button.dataset.coachQuestion)});
$('#coachForm').addEventListener('submit',async event=>{event.preventDefault();const question=$('#coachQuestion').value.trim();if(!question)return;const answer=$('#coachAnswer'),button=$('#coachSubmit'),topic=coachTopic;answer.className='coach-answer loading';answer.textContent=`Codex 正在结合聚合趋势分析${coachGuidance[topic].label}问题，通常需要十几秒…`;button.disabled=true;try{const value=await jsonFetch('/api/ai/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,topic})});answer.className='coach-answer ai-rich';answer.innerHTML=value.answer?aiMarkup(value.answer):'<p>暂未返回分析结果。</p>'}catch(e){answer.className='coach-answer';answer.textContent='分析失败：'+e.message}finally{button.disabled=false}});
renderCoachGuidance();
function assistantRequestHistory(){const out=[];let total=0;for(const item of [...assistantHistory.slice(-12)].reverse()){const content=String(item.content||'').slice(0,4000);if(!content||total+content.length>24000)continue;total+=content.length;out.push({role:item.role,content})}return out.reverse()}
const assistantModels={'auto':'自动','gpt-5.6-luna':'Luna · 快速','gpt-5.6-terra':'Terra · 均衡','gpt-5.6-sol':'Sol · 深度'};
const assistantModelLabel=model=>assistantModels[model]||assistantModels.auto;
function saveAssistantState(){try{const saved=assistantHistory.slice(-20).map(item=>({role:item.role,content:String(item.content||'').slice(0,30000),provider:item.provider||'',model:item.model||''}));localStorage.setItem('airHealthAssistantHistory',JSON.stringify(saved));localStorage.setItem('airHealthAssistantHealth',String($('#assistantHealthContext').checked));localStorage.setItem('airHealthAssistantModel',$('#assistantModel').value)}catch(e){}}
function loadAssistantState(){try{const stored=JSON.parse(localStorage.getItem('airHealthAssistantHistory')||'[]');assistantHistory=Array.isArray(stored)?stored.filter(x=>x&&['user','assistant'].includes(x.role)&&typeof x.content==='string').slice(-20):[];$('#assistantHealthContext').checked=localStorage.getItem('airHealthAssistantHealth')==='true';const model=localStorage.getItem('airHealthAssistantModel')||'auto';$('#assistantModel').value=assistantModels[model]?model:'auto'}catch(e){assistantHistory=[];$('#assistantModel').value='auto'}}
function renderAssistantMessages(){const box=$('#assistantMessages');if(!assistantHistory.length){box.innerHTML='<div class="assistant-empty"><span>✦</span><h3>直接问我任何问题</h3><p>输入文字即可开始；也可以选择一张图片，询问图片内容、截图报错或图表信息。</p></div>';return}box.innerHTML=assistantHistory.map((item,index)=>{const image=item.image_preview?`<img class="assistant-message-image" src="${esc(item.image_preview)}" alt="${esc(item.image_name||'用户上传图片')}">`:'';const userText=item.content?`<div class="assistant-user-text">${esc(item.content)}</div>`:'';return`<article class="assistant-message ${item.role==='user'?'user':'assistant'} ${image?'has-image':''}"><span class="assistant-avatar">${item.role==='user'?'你':'AI'}</span><div class="assistant-bubble ${item.role==='assistant'?'ai-rich':''}">${item.role==='assistant'?aiMarkup(item.content):image+userText}${item.role==='assistant'?`<div class="assistant-message-meta"><span>${esc(item.provider||'Codex')} · ${esc(assistantModelLabel(item.model))}</span><button class="assistant-copy" type="button" data-assistant-copy="${index}">复制</button></div>`:''}</div></article>`}).join('');requestAnimationFrame(()=>{box.scrollTop=box.scrollHeight})}
function renderAssistantImagePreview(){const panel=$('#assistantImagePreview');panel.classList.toggle('hidden',!assistantPendingImage);if(!assistantPendingImage){$('#assistantImageThumb').removeAttribute('src');return}$('#assistantImageThumb').src=assistantPendingImage.preview;$('#assistantImageName').textContent=assistantPendingImage.name;$('#assistantImageMeta').textContent=`${assistantPendingImage.width} × ${assistantPendingImage.height} · ${(assistantPendingImage.size/1024/1024).toFixed(1)} MB`}
const fileDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('图片读取失败'));reader.readAsDataURL(file)});
const loadImage=dataUrl=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('图片格式无法识别'));image.src=dataUrl});
const canvasBlob=(canvas,type,quality)=>new Promise(resolve=>canvas.toBlob(resolve,type,quality));
async function prepareAssistantImage(file){const supported=['image/jpeg','image/png','image/webp'];if(!supported.includes(file.type))throw new Error('仅支持 JPG、PNG 或 WEBP 图片');if(file.size>15*1024*1024)throw new Error('原始图片不能超过 15 MB');const original=await fileDataUrl(file),image=await loadImage(original);let payload=original,mime=file.type,size=file.size;if(file.size>2.5*1024*1024){const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await canvasBlob(canvas,'image/jpeg',.84);if(!blob||blob.size>3*1024*1024)throw new Error('图片压缩后仍然过大，请换一张图片');payload=await fileDataUrl(blob);mime='image/jpeg';size=blob.size}return{name:file.name.slice(0,120),mime_type:mime,data:payload.split(',',2)[1],preview:payload,size,width:image.naturalWidth,height:image.naturalHeight}}
$('#assistantHealthContext').addEventListener('change',()=>{saveAssistantState();$('#assistantStatus').textContent=$('#assistantHealthContext').checked?'本次会话可使用近 35 天聚合健康摘要':'对话记录仅保存在当前浏览器'});
$('#assistantModel').addEventListener('change',()=>{saveAssistantState();$('#assistantStatus').textContent=`已选择 ${assistantModelLabel($('#assistantModel').value)} 模型`});
$('#assistantClear').addEventListener('click',()=>{assistantHistory=[];assistantPendingImage=null;renderAssistantImagePreview();saveAssistantState();renderAssistantMessages();toast('AI 对话已从当前浏览器清空')});
$('#assistantMessages').addEventListener('click',async event=>{const button=event.target.closest('[data-assistant-copy]');if(!button)return;const item=assistantHistory[Number(button.dataset.assistantCopy)];if(!item)return;try{await navigator.clipboard.writeText(item.content);button.textContent='已复制'}catch(e){toast('复制失败，请长按选择文字')}});
$('#assistantImage').addEventListener('change',async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;$('#assistantStatus').textContent='正在读取图片…';try{assistantPendingImage=await prepareAssistantImage(file);renderAssistantImagePreview();$('#assistantStatus').textContent='图片已就绪，可输入问题后发送';$('#assistantInput').focus()}catch(e){assistantPendingImage=null;renderAssistantImagePreview();toast(e.message);$('#assistantStatus').textContent='图片选择失败'}});
$('#assistantImageRemove').addEventListener('click',()=>{assistantPendingImage=null;renderAssistantImagePreview();$('#assistantStatus').textContent='图片已移除'});
$('#assistantForm').addEventListener('submit',async event=>{event.preventDefault();const input=$('#assistantInput'),rawMessage=input.value.trim(),sentImage=assistantPendingImage;if(!rawMessage&&!sentImage)return;const message=rawMessage||(sentImage?'请描述并分析这张图片。':''),button=$('#assistantSend'),health=$('#assistantHealthContext').checked,model=$('#assistantModel').value,modelLabel=assistantModelLabel(model),prior=assistantRequestHistory();assistantHistory.push({role:'user',content:message,image_preview:sentImage?.preview,image_name:sentImage?.name});assistantPendingImage=null;renderAssistantImagePreview();input.value='';renderAssistantMessages();const box=$('#assistantMessages'),thinking=document.createElement('div');thinking.className='assistant-thinking';thinking.textContent=sentImage?`${modelLabel} 正在查看图片并组织回答…`:`${modelLabel} 正在组织回答…`;box.appendChild(thinking);box.scrollTop=box.scrollHeight;button.disabled=true;$('#assistantStatus').textContent=sentImage?`${modelLabel} 正在临时处理图片…`:health?`${modelLabel} 正在使用聚合健康摘要…`:`正在使用 ${modelLabel} 隔离临时会话…`;try{const image=sentImage?{name:sentImage.name,mime_type:sentImage.mime_type,data:sentImage.data}:null;const value=await jsonFetch('/api/assistant/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,history:prior,include_health:health,image,model})});assistantHistory.push({role:'assistant',content:String(value.answer||'暂未返回内容。').slice(0,30000),provider:value.provider||'Codex',model:value.model||model});saveAssistantState();renderAssistantMessages();const usedModel=assistantModelLabel(value.model||model);$('#assistantStatus').textContent=value.image_used?`${usedModel} 已处理图片并删除临时文件`:value.health_context_used?`${usedModel} 已使用近 35 天聚合健康摘要`:`${usedModel} · 未读取健康数据`}catch(e){assistantHistory.pop();assistantPendingImage=sentImage;renderAssistantImagePreview();input.value=rawMessage;renderAssistantMessages();toast('AI 助手请求失败：'+e.message);$('#assistantStatus').textContent='发送失败，可重试'}finally{button.disabled=false}});
$('#assistantInput').addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();$('#assistantForm').requestSubmit()}});
function workoutAiSection(index){return`<section class="detail-section workout-ai-section"><div class="detail-section-head"><h3>AI 单次运动解读</h3><span>按需生成</span></div><p class="workout-ai-intro">结合本次时长、心率、强度、热量、恢复与同类历史，生成更完整的训练回顾。</p><button class="workout-ai-button" type="button" data-workout-ai="${index}">✦ 分析本次运动</button><div class="workout-ai-answer"><div class="answer-placeholder"><span>✦</span><p>不会发送 GPS 坐标或逐点心率。</p></div></div></section>`}
const baseOpenWorkoutDetailWithAi=openWorkoutDetail;
openWorkoutDetail=index=>{baseOpenWorkoutDetailWithAi(index);const nav=$('#workoutDetailBody .detail-navigation'),item=currentWorkouts[index];if(nav&&item)nav.insertAdjacentHTML('beforebegin',personalRecordSection(item)+workoutAiSection(index))};
$('#workoutDetailBody').addEventListener('click',async event=>{const button=event.target.closest('[data-workout-ai]');if(!button)return;const index=Number(button.dataset.workoutAi),item=currentWorkouts[index],answer=button.parentElement.querySelector('.workout-ai-answer');if(!item||!answer)return;button.disabled=true;answer.className='workout-ai-answer loading';answer.textContent='Codex 正在比较本次运动、心率反应与同类历史…';try{const value=await jsonFetch('/api/ai/workout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({started_at:item.started_at})});answer.className='workout-ai-answer ai-rich';answer.innerHTML=`${aiMarkup(value.answer||'暂未返回分析结果。')}<p class="ai-result-meta">${value.cached?'读取缓存':'新生成'} · ${esc(value.provider||'Codex')}</p>`;button.textContent='重新查看分析'}catch(e){answer.className='workout-ai-answer';answer.textContent='分析失败：'+e.message}finally{button.disabled=false}});
